<?php
require __DIR__ . '/../config/config.php';
session_start();
if (empty($_SESSION['user_id'])) { header('Location: login.php'); exit; }
$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT * FROM orders WHERE id=? AND user_id=? LIMIT 1');$q->execute([$id,$_SESSION['user_id']]);$order=$q->fetch();if(!$order){header('Location: dashboard.php');exit;}$q=db()->prepare('SELECT * FROM order_items WHERE order_id=?');$q->execute([$id]);$items=$q->fetchAll();
?><!doctype html><html lang="bn"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Order #<?=e($id)?></title><link rel="stylesheet" href="../assets/style.css"></head><body><header><div class="logo">G</div><strong><?=e(setting('site_name','GadgetMart'))?></strong><nav><a href="dashboard.php">ড্যাশবোর্ড</a><a href="../products.php">শপ</a><a href="logout.php">লগআউট</a></nav></header><main class="page-shell"><section class="panel"><h1>অর্ডার #<?=e($id)?></h1><p>স্ট্যাটাস: <b><?=e($order['status'])?></b></p><p>পেমেন্ট: <?=e($order['payment_method']??'cod')?> / <?=e($order['payment_status']??'unpaid')?></p><p>ঠিকানা: <?=e($order['address'])?></p><div class="table-wrap"><table><tr><th>পণ্য</th><th>পরিমাণ</th><th>মূল্য</th><th>মোট</th></tr><?php foreach($items as $item):?><tr><td><?=e($item['product_name'])?></td><td><?=e($item['quantity'])?></td><td>৳<?=e(number_format((float)$item['unit_price'],2))?></td><td>৳<?=e(number_format((float)$item['unit_price']*$item['quantity'],2))?></td></tr><?php endforeach;?></table></div><h3>মোট: ৳<?=e(number_format((float)$order['total'],2))?></h3></section></main></body></html>
